def get_icon_svg(name: str, size: int = 18, color: str = "currentColor") -> str:
    """Return raw SVG string for an icon."""
    template = ICONS.get(name, ICONS["info"])
    return template.format(size=size, color=color)

def render_icon(name: str, size: int = 18, color: str = "currentColor", extra_class: str = "") -> str:
    """Return HTML inline element with SVG icon."""
    svg = get_icon_svg(name, size, color)
    return f'<span class="svg-icon {extra_class}" style="display:inline-flex; align-items:center; justify-content:center; vertical-align:-3px; line-height:1;">{svg}</span>'
